def get_latency_playbook() -> list[dict[str, Any]]:
    return copy.deepcopy(CURATION_LATENCY_PLAYBOOK)


def _default_reference_answer(record: dict[str, Any]) -> str:
    expected_facts = [fact.strip() for fact in record.get("expected_facts", []) if fact]
    if expected_facts:
        return " ".join(f"{idx + 1}. {fact}." for idx, fact in enumerate(expected_facts))
    for field in ("historical_ground_truth", "graph_ground_truth"):
        value = (record.get(field) or "").strip()
        if value.startswith("Expected facts: "):
            value = value.replace("Expected facts: ", "", 1)
        if value:
            return value
    return ""


def _default_validation_status(record: dict[str, Any]) -> str:
    if record.get("status") == "candidate":
        return "needs_review"
    if record.get("source_type", "").endswith("_generated"):
        return "needs_review"
    if _default_reference_answer(record):
        return "provisional"
    return "needs_review"


def _quality_score(rubric_assessment: dict[str, Any] | None) -> float | None:
    if not rubric_assessment:
        return None
    values = [
        rubric_assessment.get(key)
        for key in RUBRIC_DIMENSIONS
        if key != "leakage_risk"
    ]
    numeric = [float(value) for value in values if isinstance(value, (int, float))]
    if not numeric:
        return None
    return round(sum(numeric) / len(numeric), 2)


def _default_recommended_status(record: dict[str, Any]) -> str:
    return "candidate" if record.get("validation_status") == "needs_review" else "active"


def _default_recommended_eval_split(record: dict[str, Any]) -> str:
    if record.get("validation_status") == "needs_review":
        return "candidate"
    rubric = record.get("rubric_assessment", {})
    leakage_risk = rubric.get("leakage_risk")
    quality = _quality_score(rubric)
    if leakage_risk is not None and leakage_risk >= 4:
        return "train"
    if quality is None:
        return record.get("eval_split", "train")
    if quality >= 4.5 and (leakage_risk or 0) <= 2:
        return "holdout"
    if quality >= 4.0:
        return "test"
    return "train"


def _default_review_priority(record: dict[str, Any]) -> str:
    if record.get("validation_status") == "needs_review":
        return "high" if record.get("eval_split") == "holdout" or record.get("coverage_policy") == "required" else "medium"
    if record.get("validation_status") == "provisional":
        return "medium"
    return "low"


def _default_split_rationale(record: dict[str, Any]) -> str:
    if record.get("validation_status") == "needs_review":
        return "Question is not yet safe for governed evaluation; keep it in candidate until the ground truth package is repaired."
    if record.get("recommended_eval_split") == "holdout":
        return "Validated, evidence-heavy question with low leakage risk; appropriate for frozen holdout."
    if record.get("recommended_eval_split") == "test":
        return "Validated regression question with stable evidence, but not strong enough or novel enough for holdout."
    return "Useful for iterative improvement, but either more memorized or more snapshot-sensitive than a governed test/holdout case."


def _latency_profile(record: dict[str, Any]) -> dict[str, Any]:
    profile = LATENCY_PROFILES.get(record.get("architecture_primary"), DEFAULT_LATENCY_PROFILE)
    return copy.deepcopy(profile)


def apply_curation_metadata(record: dict[str, Any]) -> dict[str, Any]:
    curated = copy.deepcopy(record)
    override = copy.deepcopy(QUESTION_CURATION_OVERRIDES.get(curated.get("question_id"), {}))

    if "status" in override:
        curated["status"] = override["status"]
    if "eval_split" in override:
        curated["eval_split"] = override["eval_split"]

    curated["reference_answer"] = override.get("reference_answer") or curated.get("reference_answer") or _default_reference_answer(curated)
    curated["ground_truth_sources"] = copy.deepcopy(override.get("ground_truth_sources", curated.get("ground_truth_sources", [])))
    curated["validation_status"] = override.get("validation_status") or curated.get("validation_status") or _default_validation_status(curated)
    curated["rubric_assessment"] = copy.deepcopy(override.get("rubric_assessment", curated.get("rubric_assessment", {})))
    curated["rubric_source"] = override.get(
        "rubric_source",
        curated.get("rubric_source") or ("manual" if curated.get("question_id") in QUESTION_CURATION_OVERRIDES or curated.get("question_id", "").startswith(("bible-curated-", "enron-curated-")) else "heuristic"),
    )

    latency_profile = _latency_profile(curated)
    latency_profile.update(copy.deepcopy(override.get("latency_profile", {})))
    curated["validation_latency_profile"] = latency_profile["profile"]
    curated["parallel_validation_safe"] = latency_profile["parallel_safe"]
    curated["recommended_validation_workers"] = latency_profile["recommended_workers"]
    curated["cache_namespace"] = latency_profile["cache_namespace"]
    curated["latency_strategy_summary"] = latency_profile["strategy_summary"]
    curated["parallelization_notes"] = latency_profile["notes"]

    curated["recommended_status"] = override.get("recommended_status") or curated.get("recommended_status") or _default_recommended_status(curated)
    curated["recommended_eval_split"] = override.get("recommended_eval_split") or curated.get("recommended_eval_split") or _default_recommended_eval_split(curated)
    curated["split_rationale"] = override.get("split_rationale") or curated.get("split_rationale") or _default_split_rationale(curated)
    curated["review_notes"] = override.get("review_notes") or curated.get("review_notes", "")
    curated["review_priority"] = override.get("review_priority") or curated.get("review_priority") or _default_review_priority(curated)
    curated["ground_truth_quality_score"] = _quality_score(curated.get("rubric_assessment"))
    curated["bucket_mismatch"] = (
        curated.get("status", "active") != curated.get("recommended_status")
        or curated.get("eval_split") != curated.get("recommended_eval_split")
    )
    return curated


def build_curation_rows(records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for record in records:
        rows.append(
            {
                "question_id": record.get("question_id"),
                "corpus": record.get("corpus"),
                "status": record.get("status"),
                "eval_split": record.get("eval_split"),
                "recommended_status": record.get("recommended_status"),
                "recommended_eval_split": record.get("recommended_eval_split"),
                "validation_status": record.get("validation_status"),
                "review_priority": record.get("review_priority"),
                "quality_score": record.get("ground_truth_quality_score"),
                "reference_answer_present": bool(record.get("reference_answer")),
                "source_count": len(record.get("ground_truth_sources", [])),
                "bucket_mismatch": record.get("bucket_mismatch"),
                "latency_profile": record.get("validation_latency_profile"),
                "parallel_safe": record.get("parallel_validation_safe"),
                "recommended_workers": record.get("recommended_validation_workers"),
                "question_text": record.get("question_text"),
            }
        )
    rows.sort(
        key=lambda row: (
            {"high": 0, "medium": 1, "low": 2}.get(row["review_priority"], 99),
            row["corpus"],
            row["validation_status"],
            row["question_id"],
        )
    )
    return rows


def build_curation_summary(records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    by_corpus: dict[str, dict[str, Any]] = {}
    for record in records:
        corpus = record.get("corpus", "unknown")
        row = by_corpus.setdefault(
            corpus,
            {
                "corpus": corpus,
                "total_questions": 0,
                "active_questions": 0,
                "candidate_questions": 0,
                "validated_questions": 0,
                "provisional_questions": 0,
                "needs_review_questions": 0,
                "bucket_mismatches": 0,
                "parallel_safe_questions": 0,
                "high_priority_reviews": 0,
            },
        )
        row["total_questions"] += 1
        if record.get("status") == "active":
            row["active_questions"] += 1
        if record.get("status") == "candidate":
            row["candidate_questions"] += 1
        if record.get("validation_status") == "validated":
            row["validated_questions"] += 1
        elif record.get("validation_status") == "provisional":
            row["provisional_questions"] += 1
        else:
            row["needs_review_questions"] += 1
        if record.get("bucket_mismatch"):
            row["bucket_mismatches"] += 1
        if record.get("parallel_validation_safe"):
            row["parallel_safe_questions"] += 1
        if record.get("review_priority") == "high":
            row["high_priority_reviews"] += 1
    return [by_corpus[key] for key in sorted(by_corpus)]
